export interface PricingPlan {
  pricingPlanId: number;
  planCode: string;
  planName: string;
  tagline?: string;
  priceMonthly: number;
  priceYearly?: number;
  currency: string;
  featuresList: string;
  ctaLabel: string;
  ctaUrl: string;
  isFeatured: boolean;
  isActive: boolean;
  sortOrder: number;
  created_At: string;
  updated_at?: string;
}

export interface PricingPlanListResponse {
  pricingPlans: PricingPlan[];
}

// GET ALL — POST /all_pricingPlans
export async function getAllPricingPlans(): Promise<PricingPlan[]> {
  const res = await fetch(BASE_URL + "/all_pricingPlans", {
    method: "POST", headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ "pricingPlans": [{}] }), // No companyId, tenant-independent
  });
  if (!res.ok) throw new Error(await res.text());
  const data: PricingPlanListResponse = await res.json();
  return data.pricingPlans ?? [];
}

// GET ONE — POST /one_pricingPlans
export async function getOnePricingPlan(pricingPlanId: number): Promise<PricingPlan | null> {
  const res = await fetch(BASE_URL + "/one_pricingPlans", {
    method: "POST", headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ pricingPlanId }),
  });
  if (!res.ok) throw new Error(await res.text());
  const data: PricingPlanListResponse = await res.json();
  return data.pricingPlans?.[0] ?? null;
}

// CREATE — action: 1
export async function createPricingPlan(payload: Omit<PricingPlan, "pricingPlanId" | "created_At" | "updated_at">): Promise<PricingPlan> {
  const res = await fetch(BASE_URL + "/pricingPlans", {
    method: "POST", headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ "pricingPlans": [{ "action": 1, ...payload }] }),
  });
  if (!res.ok) throw new Error(await res.text());
  return await res.json();
}

// UPDATE — action: 2
export async function updatePricingPlan(pricingPlanId: number, payload: Partial<Omit<PricingPlan, "pricingPlanId" | "created_At" | "updated_at">>): Promise<PricingPlan> {
  const res = await fetch(BASE_URL + "/pricingPlans", {
    method: "POST", headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ "pricingPlans": [{ "action": 2, pricingPlanId, ...payload }] }),
  });
  if (!res.ok) throw new Error(await res.text());
  return await res.json();
}

// DELETE — action: 3
export async function deletePricingPlan(pricingPlanId: number): Promise<void> {
  const res = await fetch(BASE_URL + "/pricingPlans", {
    method: "POST", headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ "pricingPlans": [{ "action": 3, pricingPlanId }] }),
  });
  if (!res.ok) throw new Error(await res.text());
}

// PUBLIC GET ALL — GET /pricingPlan/public
export async function getPublicPricingPlans(): Promise<PricingPlan[]> {
  const res = await fetch(BASE_URL + "/pricingPlan/public", {
    method: "GET", headers: { "Content-Type": "application/json" },
  });
  if (!res.ok) throw new Error(await res.text());
  const data: PricingPlanListResponse = await res.json();
  return data.pricingPlans ?? [];
}
