                  type="number"
                  value={sortOrder}
                  onIonInput={(e: CustomEvent<InputInputEventDetail>) => setSortOrder(parseInt(e.detail.value!, 10))}
                  className={formErrors.sortOrder ? 'ion-invalid ion-touched' : ''}
                  errorText={formErrors.sortOrder}
                />
              </div>
              <IonButton expand="block" onClick={handleSavePlan} disabled={saving}>
                {saving ? <IonSpinner name="dots" /> : (selectedPlan ? 'Save Changes' : 'Add Plan')}
              </IonButton>
            </form>
          </IonContent>
        </IonModal>

        <IonLoading isOpen={loading} message={'Loading pricing plans...'}>
          <IonSpinner name="crescent"></IonSpinner>
        </IonLoading>

        <IonToast
          isOpen={!!error}
          message={error}
          duration={3000}
          onDidDismiss={() => setError('')}
          color="danger"
        />

        <IonAlert
          isOpen={showDeleteAlert}
          onDidDismiss={() => setShowDeleteAlert(false)}
          header={'Confirm Delete'}
          message={`Are you sure you want to delete the pricing plan "${planToDelete?.planName}"?`}
          buttons={[
            { text: 'Cancel', role: 'cancel' },
            { text: 'Delete', handler: confirmDelete, cssClass: 'danger' },
          ]}
        />
      </IonContent>
    </IonPage>
  );
};

export default PricingPlanPage;
